// Get the sub-workflow result and the original test case
const result = $input.first().json;
const testCase = $('Loop Over Tests').first().json;

var testName = testCase._testName;
var expectReview = testCase._expectReviewNeeded;
var scenario = testCase._scenario;

// Determine actual outcome
var actualReview = result.needsHumanReview === true;

// Compare: did the sub-workflow produce the expected outcome?
var testPassed = (expectReview === actualReview);

var status = testPassed ? 'TEST PASSED' : 'TEST FAILED';
var detail = '';
if (!testPassed) {
  if (expectReview) {
    detail = 'Expected sub-workflow to FLAG this output for review, but it PASSED it through.';
  } else {
    detail = 'Expected sub-workflow to PASS this output, but it FLAGGED it for review.';
  }
} else {
  detail = expectReview
    ? 'Correctly flagged for human review.'
    : 'Correctly passed without flagging.';
}

var resultObj = {
  testName: testName,
  scenario: scenario,
  testStatus: status,
  testPassed: testPassed,
  detail: detail,
  expectedReviewNeeded: expectReview,
  actualReviewNeeded: actualReview,
  confidenceScore: result.confidenceScore != null ? result.confidenceScore : 'N/A',
  overallAssessment: result.overallAssessment || 'N/A',
  passed: result.passed != null ? result.passed : 'N/A',
  reviewLevel: result.reviewLevel || 'NONE',
  decisionSummary: result.decisionSummary || '',
  flaggedIssuesCount: result.flaggedIssues ? result.flaggedIssues.length : 0,
  unsourcedClaimCount: result.unsourcedClaimCount != null ? result.unsourcedClaimCount : 0,
  totalClaimsChecked: result.totalClaimsChecked != null ? result.totalClaimsChecked : 0
};

// Accumulate results in workflow static data so Aggregate Results can read ALL iterations
var staticData = $getWorkflowStaticData('global');
if (!Array.isArray(staticData._testResults)) {
  staticData._testResults = [];
}
staticData._testResults.push(resultObj);

return [{ json: resultObj }];

// Read all accumulated test results from workflow static data
var staticData = $getWorkflowStaticData('global');
var allResults = staticData._testResults || [];

// Clear the accumulator for the next run
delete staticData._testResults;

var totalTests = allResults.length;
var testsPassed = 0;
var testsFailed = 0;
var rows = '';

for (var i = 0; i < allResults.length; i++) {
  var r = allResults[i];
  if (r.testPassed) {
    testsPassed++;
  } else {
    testsFailed++;
  }

  var statusColor = r.testPassed ? '#28a745' : '#dc3545';
  var statusIcon = r.testPassed ? 'PASS' : 'FAIL';

  rows += '<tr>' +
    '<td style="padding:10px;border:1px solid #ddd;">' + (i + 1) + '</td>' +
    '<td style="padding:10px;border:1px solid #ddd;font-weight:bold;color:' + statusColor + ';">' + statusIcon + '</td>' +
    '<td style="padding:10px;border:1px solid #ddd;">' + r.testName + '</td>' +
    '<td style="padding:10px;border:1px solid #ddd;text-align:center;">' + r.confidenceScore + '</td>' +
    '<td style="padding:10px;border:1px solid #ddd;">' + r.overallAssessment + '</td>' +
    '<td style="padding:10px;border:1px solid #ddd;text-align:center;">' + (r.expectedReviewNeeded ? 'Yes' : 'No') + '</td>' +
    '<td style="padding:10px;border:1px solid #ddd;text-align:center;">' + (r.actualReviewNeeded ? 'Yes' : 'No') + '</td>' +
    '<td style="padding:10px;border:1px solid #ddd;">' + r.detail + '</td>' +
    '</tr>';
}

var overallColor = testsFailed === 0 ? '#28a745' : '#dc3545';
var overallStatus = testsFailed === 0 ? 'ALL TESTS PASSED' : testsFailed + ' TEST(S) FAILED';

var reportHtml = '<div style="font-family:Arial,sans-serif;max-width:1000px;margin:0 auto;">' +
  '<div style="background:' + overallColor + ';color:white;padding:20px;border-radius:8px 8px 0 0;">' +
  '<h2 style="margin:0;">AI Validation Test Harness Results</h2>' +
  '<p style="margin:6px 0 0;font-size:18px;">' + overallStatus + ' (' + testsPassed + '/' + totalTests + ')</p>' +
  '</div>' +
  '<div style="padding:16px;border:1px solid #ddd;border-top:none;">' +
  '<table style="width:100%;border-collapse:collapse;">' +
  '<tr style="background:#f5f5f5;">' +
  '<th style="padding:10px;border:1px solid #ddd;">#</th>' +
  '<th style="padding:10px;border:1px solid #ddd;">Result</th>' +
  '<th style="padding:10px;border:1px solid #ddd;">Test Scenario</th>' +
  '<th style="padding:10px;border:1px solid #ddd;">Score</th>' +
  '<th style="padding:10px;border:1px solid #ddd;">Assessment</th>' +
  '<th style="padding:10px;border:1px solid #ddd;">Expected Review</th>' +
  '<th style="padding:10px;border:1px solid #ddd;">Actual Review</th>' +
  '<th style="padding:10px;border:1px solid #ddd;">Detail</th>' +
  '</tr>' +
  rows +
  '</table>' +
  '<div style="margin-top:16px;padding:12px;background:#f9f9f9;border-radius:4px;">' +
  '<strong>Summary:</strong> ' + totalTests + ' tests executed. ' +
  '<span style="color:#28a745;font-weight:bold;">' + testsPassed + ' passed</span>, ' +
  '<span style="color:' + (testsFailed > 0 ? '#dc3545' : '#28a745') + ';font-weight:bold;">' + testsFailed + ' failed</span>.' +
  '</div>' +
  '</div></div>';

var subject = testsFailed === 0
  ? '[TEST HARNESS] ALL PASSED - ' + testsPassed + '/' + totalTests + ' scenarios'
  : '[TEST HARNESS] ' + testsFailed + ' FAILED - ' + testsPassed + '/' + totalTests + ' passed';

return [{
  json: {
    totalTests: totalTests,
    testsPassed: testsPassed,
    testsFailed: testsFailed,
    allPassed: testsFailed === 0,
    overallStatus: overallStatus,
    emailSubject: subject,
    reportHtml: reportHtml,
    results: allResults
  }
}];
